    !SUPPORTED_INPUT_VERSIONS.includes(version) &&
    version < USER_CONFIG_VERSION
  ) {
    throw new ConfigValidationError(
      "version",
      `unsupported config version ${JSON.stringify(version)}; expected one of ${SUPPORTED_INPUT_VERSIONS.join(", ")}`,
    );
